"""Original diabetes chapter three: prevention and recognition of organ complications."""
from create_diabetes_therapeutics import rows,q,PH,CK,CV,EF
from qbank_authoring import ref,finalize
FI=ref('IWGDF/IDSA: Diabetes-Related Foot Infections, 2023','https://www.idsociety.org/practice-guideline/diabetic-foot-infections/')
FO=ref('IWGDF: Practical Guidelines on Diabetes-Related Foot Disease, 2023','https://onlinelibrary.wiley.com/doi/full/10.1002/dmrr.3657')
LI=ref('AHA/ACC Multisociety Dyslipidemia Guideline, 2026','https://www.ahajournals.org/doi/pdf/10.1161/CIR.0000000000001423')
q('Which kidney screening approach is recommended in type 2 diabetes?', 'At least annual urine albumin-to-creatinine ratio and eGFR assessment starting at diagnosis',[
 ('Urine dipstick protein alone every five years','It can miss moderately increased albumin and does not assess GFR.'),('Begin only after retinopathy develops','Kidney disease can occur without documented retinopathy.'),('Creatinine alone is sufficient to exclude albuminuric disease','Albuminuria can precede a major filtration decline.')],
 'Albuminuria and filtration provide complementary risk information', '**A spot UACR detects albumin loss while eGFR assesses filtration.**',['Type 2 diabetes may have existed before clinical diagnosis.','More frequent monitoring is appropriate with established CKD.'], '**Interpret trends and confirm persistent abnormalities.**',['Exercise, infection and marked hyperglycemia can transiently raise albumin.','Do not assume every renal abnormality is caused by diabetes.'],[['UACR','Albumin leakage'],['eGFR','Filtration'],['Type 2 timing','From diagnosis']],[CK])
q('One UACR is 85 mg/g during a febrile urinary infection. What is the best diagnostic approach?', 'Repeat after transient factors resolve to establish persistent albuminuria',[
 ('Diagnose irreversible diabetic nephropathy from this sample alone','Infection can transiently raise albumin.'),('Ignore all future kidney testing because the value is below 300','Moderately increased albuminuria is clinically relevant if persistent.'),('A normal eGFR excludes kidney disease regardless of albumin','Persistent albuminuria can establish CKD with preserved GFR.')],
 'Biological variation makes confirmation important', '**Typically two of three abnormal UACR samples over three to six months support persistent albuminuria.**',['Exercise, menstruation, fever and heart failure can confound measurements.','A very atypical pattern needs additional evaluation.'], '**Treat the acute trigger and arrange follow-up.**',['Use both albumin and eGFR for risk classification.','Avoid irreversible diagnostic labels from one confounded result.'],[['Single result','Potentially transient'],['Persistence','Confirm on repeated samples'],['Risk assessment','UACR plus eGFR']],[CK],'clinical_scenario')
q('A patient with diabetes has hypertension, UACR 420 mg/g and eGFR 55. Which antihypertensive strategy has a kidney-protective role?', 'An ACE inhibitor or ARB titrated to the maximum tolerated dose with creatinine and potassium monitoring',[
 ('Combine ACE inhibitor and ARB routinely for extra benefit','Dual blockade increases adverse-event risk without the desired outcome advantage.'),('Avoid all RAAS blockade solely because albumin is high','Albuminuric hypertension is an important indication.'),('Use no blood-pressure therapy if A1C is controlled','Glycemia does not remove hypertension-related renal risk.')],
 'Albuminuric hypertension is a specific treatment context', '**Single-agent RAAS blockade reduces albuminuric kidney risk in appropriate patients.**',['Monitor for hyperkalemia and significant creatinine changes.','Pregnancy and other contraindications change eligibility.'], '**Do not confuse an expected hemodynamic change with every form of AKI.**',['Assess volume and interacting drugs if renal function worsens.','Use complementary organ-protective therapy where indicated.'],[['Indication','Diabetes plus hypertension and albuminuria'],['Choice','ACE inhibitor or ARB'],['Avoid','Routine dual RAAS blockade']],[CK],'clinical_scenario')
q('Albuminuric CKD persists in type 2 diabetes despite tolerated ACE inhibitor and SGLT2 therapy. eGFR is 42 and potassium is normal. Which additional class has proven kidney and cardiovascular benefit?', 'A nonsteroidal mineralocorticoid receptor antagonist such as finerenone',[
 ('A second ACE inhibitor added to the first','This is not an appropriate evidence-based combination.'),('An NSAID to reduce glomerular filtration pressure chronically','This can worsen kidney function and volume control.'),('Potassium supplementation automatically despite normal potassium','This can increase risk without an indication.')],
 'Layer complementary protection in an eligible patient', '**Finerenone has outcome evidence in type 2 diabetes with albuminuric CKD.**',['Eligibility generally includes eGFR at least 25 and acceptable potassium.','Monitoring is essential because hyperkalemia can occur.'], '**Review volume, potassium and the full medication list.**',['Do not substitute this for appropriate RAAS and SGLT2 treatment when tolerated.','Use the current product and guideline dosing pathway.'],[['Residual risk','Persistent albuminuria'],['Additional therapy','Finerenone when eligible'],['Monitoring','Potassium and eGFR']],[CK,CV],'clinical_scenario')
q('When should an adult with newly diagnosed type 2 diabetes have an initial comprehensive dilated eye assessment?', 'At diagnosis',[
 ('Only five years after diagnosis as in the usual type 1 schedule','Type 2 disease may predate diagnosis.'),('Only if visual symptoms appear','Sight-threatening disease can initially be asymptomatic.'),('Only after kidney failure develops','This would miss earlier preventable disease.')],
 'Retinal screening is preventive rather than symptom-triggered', '**Type 2 diabetes requires assessment at diagnosis.**',['For type 1 diabetes, an initial adult examination is generally within five years of onset.','Follow-up frequency depends on findings and risk.'], '**Use validated screening pathways and appropriate referral.**',['Retinal photography or approved AI screening can support access.','Positive or ungradable results require an eye-care pathway.'],[['Type 2','At diagnosis'],['Type 1','Generally within five years'],['Symptoms','Not required for screening']],[EF])
q('A patient has center-involving diabetic macular edema with impaired visual acuity. Which treatment is first line for most affected eyes?', 'Intravitreal anti-VEGF therapy',[
 ('Routine systemic corticosteroids as the standard first choice','They are not the usual first-line approach for this indication.'),('Panretinal photocoagulation as the same treatment for every macular edema case','PRP principally addresses proliferative ischemic drive, not all center-involving edema.'),('Observation until severe irreversible loss in every case','Visual impairment with center involvement often warrants treatment.')],
 'Match ocular therapy to the lesion', '**Anti-VEGF reduces vascular permeability and edema.**',['Treatment choice also considers anatomy, response and follow-up capacity.','Selected eyes may need other intravitreal or laser strategies.'], '**Coordinate ongoing ophthalmic monitoring.**',['Systemic glucose, blood pressure and lipid care remain important.','Do not substitute systemic risk control for indicated local therapy.'],[['Center-involving edema with vision loss','Usually anti-VEGF'],['Proliferative disease','PRP and/or anti-VEGF pathway'],['Systemic care','Complementary risk control']],[EF],'clinical_scenario')
q('Neovascularization at the optic disc and vitreous hemorrhage occur in diabetes. What is the key management implication?', 'Prompt ophthalmic treatment for proliferative retinopathy, using PRP and/or an appropriate anti-VEGF strategy',[
 ('Wait for A1C improvement before referral','Treatment delay can risk vision.'),('This is merely uncomplicated early nonproliferative disease','Neovascularization defines proliferative disease.'),('No eye therapy is useful once new vessels appear','Effective therapies reduce severe vision-loss risk.')],
 'Ischemic retinal neovascularization is sight threatening', '**Fragile new vessels can bleed and contribute to traction.**',['Panretinal photocoagulation reduces the ischemic stimulus.','Anti-VEGF is an alternative or adjunct in selected settings with reliable follow-up.'], '**Select the strategy with an ophthalmologist.**',['Vitreoretinal surgery may be needed for particular complications.','Include adherence and visit burden in treatment selection.'],[['Finding','Neovascularization'],['Classification','Proliferative retinopathy'],['Therapy','PRP/anti-VEGF according to context']],[EF],'clinical_scenario')
q('What is the main purpose of a 10-g monofilament assessment during the diabetic foot examination?', 'Detecting loss of protective sensation and ulcer risk',[
 ('Excluding every small-fiber neuropathy if normal','Small-fiber symptoms can occur before monofilament loss.'),('Measuring arterial blood flow directly','Vascular assessment is separate.'),('Identifying the specific cause of every neuropathy','The test does not establish etiology.')],
 'Different bedside tests assess different nerve functions', '**Monofilament loss signals vulnerability to unnoticed trauma.**',['Vibration and pinprick or temperature add complementary information.','Pulses, deformity and skin inspection are also essential.'], '**Translate findings into prevention.**',['Teach daily inspection and suitable footwear.','Increase surveillance for prior ulcer or amputation and other high-risk features.'],[['Monofilament','Protective sensation'],['Other tests','Large- and small-fiber function'],['Full foot exam','Neurological, vascular and structural']],[EF,FO])
q('Painful distal symmetrical neuropathy persists despite optimized general care. Which pharmacological choice is a reasonable initial option?', 'Duloxetine or another recommended neuropathic-pain class selected for comorbidity and tolerance',[
 ('Long-term opioid treatment as the preferred routine first step','Guidelines discourage routine opioid use for diabetic neuropathic pain.'),('Higher insulin doses solely to produce immediate analgesia','Glycemic treatment does not function as a rapid pain medicine.'),('Antibiotics without evidence of infection','This does not treat neuropathic pain.')],
 'Pain control and nerve-damage prevention are different goals', '**SNRIs, gabapentinoids and other recommended classes can reduce symptoms.**',['Kidney function, falls, mood and drug interactions influence choice.','No one agent is ideal for every patient.'], '**Evaluate alternative causes and functional effects.**',['Rapid, asymmetric or motor-predominant disease is atypical.','Assess sleep and mood and use a monitored therapeutic trial.'],[['Goal','Symptom and function improvement'],['Selection','Comorbidity and safety'],['Avoid','Routine opioid escalation']],[EF])
q('Early satiety, vomiting of retained food and erratic postmeal glucose suggest gastroparesis in diabetes. Which diagnostic principle is correct?', 'Exclude mechanical obstruction and document delayed gastric emptying using a validated test when indicated',[
 ('Symptoms alone prove diabetic autonomic gastroparesis in every case','Obstruction, drugs and other causes must be considered.'),('A normal fasting glucose excludes delayed emptying','Gastric motor function is not determined by one fasting value.'),('Routine escalation of a gastric-slowing drug is always appropriate','Such drugs can aggravate the problem.')],
 'Symptoms and objective physiology must be connected', '**Autonomic dysfunction can delay nutrient delivery and mismatch prandial insulin.**',['Opioids and GLP-1 therapies can slow emptying.','Acute hyperglycemia can also affect gastric function.'], '**Use dietetic and specialist management.**',['Smaller suitable meals and medication review can help.','Severe vomiting or dehydration requires prompt assessment.'],[['First exclusion','Mechanical obstruction'],['Confirmation','Validated gastric-emptying assessment'],['Glycemic issue','Insulin-nutrient mismatch']],[EF],'clinical_scenario')
q('A patient with long-standing diabetes has orthostatic dizziness and a sustained blood-pressure fall with little compensatory heart-rate increase. Which mechanism is concerning?', 'Cardiovascular autonomic neuropathy',[
 ('Autonomic disease is proven without excluding medication or volume causes','Those causes must still be evaluated.'),('The findings specifically prove primary aldosteronism','That usually produces a different blood-pressure phenotype.'),('Only peripheral sensory fibers can be affected in diabetes','Autonomic nerves can also be involved.')],
 'Assess symptoms and reversible contributors before assigning cause', '**Impaired autonomic reflexes can reduce orthostatic compensation.**',['Diuretics, vasodilators, dehydration and cardiac disease can mimic or compound it.','Resting tachycardia can be another autonomic clue.'], '**Individualize volume, medication and nonpharmacological measures.**',['Supine hypertension complicates treatment in some patients.','Specialist drugs may be needed for persistent disabling symptoms.'],[['Clue','Postural fall with impaired compensation'],['Differential','Drugs, depletion and cardiac causes'],['Management','Cause review and individualized support']],[EF],'clinical_scenario')
q('A painless plantar ulcer is present beneath a metatarsal head with surrounding callus and adequate perfusion. Which intervention is central to healing?', 'Effective pressure offloading plus appropriate wound care',[
 ('Antibiotics alone despite no clinical infection','Antibiotics do not remove mechanical pressure.'),('Continue unrestricted walking in the same shoes','Repeated load sustains injury.'),('Topical antiseptic alone as a complete strategy','This does not address the ulcer’s mechanical cause.')],
 'A neuropathic ulcer is also a pressure problem', '**Loss of protective sensation permits repetitive unnoticed trauma.**',['A suitable nonremovable knee-high device is often preferred for uncomplicated plantar forefoot or midfoot ulcers when not contraindicated.','Infection, ischemia and practical safety can change device selection.'], '**Assess vascular supply and infection as well.**',['Debridement and dressings are part of a wider plan.','Prevent recurrence with footwear, inspection and follow-up.'],[['Driver','Repetitive plantar load'],['Key treatment','Offloading'],['Additional care','Wound, vascular and infection assessment']],[FO],'clinical_scenario')
q('A chronic diabetic foot ulcer grows bacteria on a swab but has no clinical signs of infection. What is the best antimicrobial principle?', 'Do not prescribe antibiotics solely to promote healing or eradicate colonization',[
 ('Every positive swab requires systemic antibiotics','Colonization is common and does not establish infection.'),('Antibiotics replace offloading in an uninfected ulcer','Mechanical and wound care remain necessary.'),('No follow-up is needed because it is uninfected today','The ulcer still requires treatment and surveillance.')],
 'Diagnose infection clinically rather than from colonization alone', '**IWGDF/IDSA advises against antibiotics for clinically uninfected ulcers.**',['Infection signs include purulence and appropriate inflammatory findings.','Neuropathy and ischemia can alter the presentation.'], '**Provide effective ulcer care and monitor for change.**',['Assess perfusion and pressure.','If infection develops, obtain a suitable specimen and treat by severity.'],[['Positive culture alone','May be colonization'],['Clinical infection','Requires assessment and treatment'],['Uninfected ulcer','No antibiotics for healing alone']],[FI],'clinical_scenario')
q('A deep diabetic foot ulcer probes to bone and plain radiography is equivocal. If osteomyelitis remains uncertain, which imaging test is generally preferred?', 'MRI',[
 ('A repeat superficial swab as definitive bone diagnosis','It does not reliably identify bone infection.'),('No further evaluation because fever is absent','Osteomyelitis can be afebrile.'),('A normal skin temperature alone excludes infection','Local and systemic signs may be muted.')],
 'Bone infection requires integration of clinical, laboratory and imaging evidence', '**Probe-to-bone, plain films and inflammatory markers are initial tools.**',['MRI is recommended when diagnostic doubt remains.','Selected nuclear techniques can be alternatives when MRI is unsuitable.'], '**Obtain bone rather than superficial samples when microbiological confirmation is needed.**',['Plan medical and surgical care according to severity, perfusion and anatomy.','Do not treat every bone-infection scenario with an identical duration or procedure.'],[['Initial tools','Probe-to-bone, x-ray and markers'],['Persistent doubt','MRI'],['Culture target','Bone when indicated']],[FI],'clinical_scenario')
q('A neuropathic patient has a warm swollen red foot with relatively little pain, intact skin and no clear systemic infection. What immediate precaution is appropriate while evaluating active Charcot neuro-osteoarthropathy?', 'Immobilize and offload promptly rather than allowing continued unprotected walking',[
 ('Normal initial x-rays exclude active Charcot disease','Early disease may not yet show characteristic radiographic changes.'),('Pain must be severe for the diagnosis to be possible','Neuropathy can blunt pain.'),('Treat only with a topical antibiotic and ignore structural disease','Mechanical protection and diagnostic assessment are essential.')],
 'Early recognition can prevent progressive deformity', '**Active Charcot disease involves inflammatory bone and joint injury in a neuropathic limb.**',['Infection, gout and thrombosis are important alternatives.','MRI can help when early radiographs are normal and suspicion persists.'], '**Arrange an urgent specialist foot pathway.**',['Use appropriate knee-high immobilization/offloading according to the clinical setting.','Monitor skin, perfusion and temperature during care.'],[['Clinical clue','Warm swollen neuropathic foot'],['Early x-ray','Can be normal'],['Immediate action','Protect from further loading']],[FO,EF],'clinical_scenario')
q('A 55-year-old with diabetes, prior MI and persistently elevated LDL despite tolerated high-intensity statin therapy asks whether A1C control is enough. What is the best response?', 'Intensify evidence-based lipid management as needed because secondary vascular risk remains high',[
 ('A1C at goal makes LDL irrelevant','Glycemic control does not replace lipid lowering.'),('Stop the statin if no angina is present','Secondary prevention is not symptom-dependent.'),('Use no LDL goal after an MI','Current guidelines use risk-based LDL goals and treatment intensification.')],
 'Treat independent modifiable risk pathways', '**The 2026 dyslipidemia guideline targets LDL below 55 mg/dL for very-high-risk ASCVD.**',['Some ASCVD patients outside that category use a goal below 70.','Ezetimibe, PCSK9-based therapy or other agents may be considered according to the needed reduction and context.'], '**Review adherence, tolerance and the complete risk profile.**',['Do not confuse symptom control with prevention.','Use the applicable guideline risk category rather than one universal diabetes number.'],[['Glycemia','One risk domain'],['Established ASCVD','Secondary lipid prevention'],['Very high risk','LDL goal below 55']],[LI],'clinical_scenario')
q('Which statement about aspirin in diabetes is most accurate?', 'It is generally indicated for secondary prevention when appropriate, while primary prevention requires individualized vascular and bleeding-risk assessment',[
 ('Every adult with diabetes requires aspirin regardless of bleeding risk','Primary prevention is selective.'),('Aspirin is never useful after an ischemic cardiovascular event','It has an established secondary-prevention role when appropriate.'),('A normal A1C eliminates the need to consider antiplatelet therapy','The indication is not determined by A1C alone.')],
 'The balance changes after an established event', '**Secondary prevention and primary prevention have different benefit-risk profiles.**',['Age, gastrointestinal bleeding, anticoagulation and other factors alter harm.','An allergy or competing antithrombotic indication changes selection.'], '**Review the full vascular history and regimen.**',['Avoid duplicate antithrombotic exposure without an indication.','Use shared decision-making for primary prevention.'],[['Secondary prevention','Usually clear role when appropriate'],['Primary prevention','Selective'],['Key harm','Bleeding']],[CV])
q('A patient with diabetes and hypertension is free of orthostatic symptoms. Which treatment principle is appropriate?', 'Aim for guideline-directed blood-pressure control when safely tolerated, accounting for cardiovascular and kidney risk',[
 ('Any low pressure is automatically beneficial despite dizziness or falls','Safety and tolerance matter.'),('A1C control removes the need for hypertension treatment','Blood pressure independently affects outcomes.'),('Only the clinic reading matters and home technique is irrelevant','Reliable repeated or out-of-office measurements improve assessment.')],
 'The number requires a reliable measurement and a safe clinical context', '**A usual diabetes target is below 130/80 mmHg when safely achievable.**',['Selected high-risk patients may benefit from more intensive systolic targets under current guidance.','Frailty and adverse effects can justify a less intensive plan.'], '**Use individualized medication selection.**',['Albuminuric CKD favors an ACE inhibitor or ARB when eligible.','Monitor electrolytes, kidney function and orthostasis after changes.'],[['Common goal','Below 130/80 if safe'],['Measurement','Reliable repeated technique'],['Individualization','Risk, tolerance and comorbidity']],[CK,CV])
q('A patient with advanced retinopathy is about to undergo a large rapid improvement in glycemia. What is the appropriate precaution?', 'Assess retinal status and arrange appropriate ophthalmic follow-up because early worsening can accompany rapid glycemic improvement',[
 ('Permanently avoid improving glucose','Long-term glycemic control remains beneficial.'),('Rapid lowering guarantees retinopathy improvement immediately','Transient worsening can occur.'),('Eye assessment is unnecessary if vision is currently normal','Retinopathy may be asymptomatic.')],
 'Short-term and long-term retinal responses can differ', '**A rapid major A1C reduction can be associated with early retinopathy worsening.**',['The baseline disease burden influences risk.','This is not a reason to leave severe hyperglycemia untreated.'], '**Coordinate metabolic and ophthalmic care.**',['Treat sight-threatening disease when indicated.','Review the pace and monitoring plan according to the clinical urgency.'],[['Long-term effect','Better control reduces risk'],['Early concern','Possible transient worsening'],['Response','Retinal assessment and follow-up']],[EF],'clinical_scenario')
q('A man with diabetes and erectile dysfunction uses a nitrate for angina. Which treatment precaution is essential?', 'Do not combine a PDE5 inhibitor with nitrate therapy because of severe hypotension risk',[
 ('The combination is always safe if A1C is controlled','The interaction is independent of A1C.'),('Erectile dysfunction has no vascular significance','It can accompany endothelial and cardiovascular disease.'),('All cases prove irreversible autonomic neuropathy','Vascular, hormonal, medication and psychological contributors require assessment.')],
 'A common symptom can reveal broader vascular disease', '**PDE5 inhibitors enhance the nitric-oxide signaling pathway.**',['Nitrates can produce a dangerous additive hypotensive effect.','Cardiovascular fitness and medication review matter before treatment.'], '**Assess the mechanism and appropriate alternatives.**',['Check for hypogonadism when clinically indicated.','Address cardiovascular risk, relationship and psychosocial factors without assuming one cause.'],[['Interaction','PDE5 inhibitor plus nitrate'],['Hazard','Severe hypotension'],['Assessment','Vascular, endocrine and other contributors']],[EF,CV],'clinical_scenario')

if __name__=='__main__':finalize('Endocrine',3,'Diabetic Complications and Therapeutics','endo-diabetes-complications',rows,40)
